      ctx.moveTo(b.x + 1, yBase - 27);
      ctx.lineTo(b.x + 17, yBase - 22 + kibar);
      ctx.lineTo(b.x + 1, yBase - 15);
      ctx.closePath();
      ctx.fillStyle = warna;
      ctx.fill();
      ctx.strokeStyle = "#1b120b";
      ctx.lineWidth = 1.2;
      ctx.stroke();
      ctx.restore();
