      ctx.lineWidth = 3.5;
      ctx.strokeStyle = "rgba(18, 12, 8, 0.92)";
      ctx.strokeText(t.teks, t.x, t.y);
      ctx.fillStyle = t.warna;
      ctx.fillText(t.teks, t.x, t.y);
