    this.setInfoSeleksi(unitTerpilih.length > 1 ? `${unitTerpilih.length} Pasukan Terpilih` : defUtama.nama, utama.hero ? `Lv${utama.level} (${utama.xp} XP) \u2022 ${NAMA_SERANGAN[defUtama.serangan]} \u2022 ${NAMA_BAJU[defUtama.baju]}` : `DMG ${utama.dmg} \u2022 ${NAMA_SERANGAN[defUtama.serangan]} \u2022 ${NAMA_BAJU[defUtama.baju]}`);
    const kunciT = "u:" + unitTerpilih.slice(0, 12).map((u) => u.id).join(",");
