        const sisaPorsi = Math.max(0, Math.min(1, hero.skillJeda / defS.jeda));
        this.skillSapuan.style.display = "block";
        this.skillSapuan.style.height = `calc(${(sisaPorsi * 100).toFixed(1)}% - 8px)`;
